def max_defended_score(n, m, k, castles, portals):
    # Initialize DP table
    dp = [[[-float('inf')] * (n + 1) for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][k][0] = 0

    # Build adjacency list for portals
    adj_list = defaultdict(list)
    for u, v in portals:
        adj_list[u].append(v)

    # Process each castle
