        a_i, b_i, c_i = castles[i - 1]

        # Update DP table for not capturing the current castle
        for j in range(k + 1):
            for l in range(i + 1):
                dp[i][j][l] = max(dp[i][j][l], dp[i - 1][j][l])

        # Update DP table for capturing the current castle
        for j in range(k + 1):
            if j >= a_i:
                for l in range(i + 1):
                    dp[i][j][l] = max(dp[i][j][l], dp[i - 1][j - a_i][l] + c_i)

        # Update DP table for defending the current castle
        for j in range(k + 1):
            for l in range(i + 1):
                if j > 0:
                    dp[i][j][l] = max(dp[i][j][l], dp[i - 1][j - 1][l] + c_i)

        # Update DP table for using portals
        for j in range(k + 1):
            for l in range(i + 1):
                for v in adj_list[i]:
                    if j > 0:
                        dp[v][j - 1][l] = max(dp[v][j - 1][l], dp[i - 1][j][l])

    # Find the maximum score among all possible states
    max_score = -float('inf')
    for j in range(k + 1):
        for l in range(n + 1):
            max_score = max(max_score, dp[n][j][l])

    return max_score if max_score != -float('inf') else -1

