import sys
from collections import defaultdict, deque

input = sys.stdin.read
data = input().split()

def solve():
    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    index = 3
    a = [0] * (n + 1)
    b = [0] * (n + 1)
    c = [0] * (n + 1)

    for i in range(1, n + 1):
        a[i] = int(data[index])
        b[i] = int(data[index + 1])
        c[i] = int(data[index + 2])
        index += 3

    portals = defaultdict(list)
    for _ in range(m):
        u = int(data[index]) - 1
        v = int(data[index + 1]) - 1
        portals[u].append(v)
        index += 2

    dp = [[[-float('inf')] * (n + 1) for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][k][0] = 0

    for i in range(1, n + 1):
        for j in range(k + 1):
            for l in range(i + 1):
                if dp[i - 1][j][l] != -float('inf'):
                    if j >= a[i]:
                        dp[i][j][l] = max(dp[i][j][l], dp[i - 1][j][l] + c[i])
                    if j + b[i] <= k:
                        dp[i][j + b[i]][l] = max(dp[i][j + b[i]][l], dp[i - 1][j][l])
                    if l > 0:
                        dp[i][j][l - 1] = max(dp[i][j][l - 1], dp[i - 1][j][l])
                    for v in portals[i]:
                        if j >= a[v]:
                            dp[v][j][l] = max(dp[v][j][l], dp[i - 1][j][l] + c[v])

    ans = -float('inf')
    for j in range(k + 1):
        for l in range(n + 1):
            ans = max(ans, dp[n][j][l])

    return ans if ans != -float('inf') else -1

